# [doc = " Parameters governing MTU discovery."] # [doc = ""] # [doc = " # The why of MTU discovery"] # [doc = ""] # [doc = " By design, QUIC ensures during the handshake that the network path between the client and the"] # [doc = " server is able to transmit unfragmented UDP packets with a body of 1200 bytes. In other words,"] # [doc = " once the connection is established, we know that the network path's maximum transmission unit"] # [doc = " (MTU) is of at least 1200 bytes (plus IP and UDP headers). Because of this, a QUIC endpoint can"] # [doc = " split outgoing data in packets of 1200 bytes, with confidence that the network will be able to"] # [doc = " deliver them (if the endpoint were to send bigger packets, they could prove too big and end up"] # [doc = " being dropped)."] # [doc = ""] # [doc = " There is, however, a significant overhead associated to sending a packet. If the same"] # [doc = " information can be sent in fewer packets, that results in higher throughput. The amount of"] # [doc = " packets that need to be sent is inversely proportional to the MTU: the higher the MTU, the"] # [doc = " bigger the packets that can be sent, and the fewer packets that are needed to transmit a given"] # [doc = " amount of bytes."] # [doc = ""] # [doc = " Most networks have an MTU higher than 1200. Through MTU discovery, endpoints can detect the"] # [doc = " path's MTU and, if it turns out to be higher, start sending bigger packets."] # [doc = ""] # [doc = " # MTU discovery internals"] # [doc = ""] # [doc = " Quinn implements MTU discovery through DPLPMTUD (Datagram Packetization Layer Path MTU"] # [doc = " Discovery), described in [section 14.3 of RFC"] # [doc = " 9000](https://www.rfc-editor.org/rfc/rfc9000.html#section-14.3). This method consists of sending"] # [doc = " QUIC packets padded to a particular size (called PMTU probes), and waiting to see if the remote"] # [doc = " peer responds with an ACK. If an ACK is received, that means the probe arrived at the remote"] # [doc = " peer, which in turn means that the network path's MTU is of at least the packet's size. If the"] # [doc = " probe is lost, it is sent another 2 times before concluding that the MTU is lower than the"] # [doc = " packet's size."] # [doc = ""] # [doc = " MTU discovery runs on a schedule (e.g. every 600 seconds) specified through"] # [doc = " [`MtuDiscoveryConfig::interval`]. The first run happens right after the handshake, and"] # [doc = " subsequent discoveries are scheduled to run when the interval has elapsed, starting from the"] # [doc = " last time when MTU discovery completed."] # [doc = ""] # [doc = " Since the search space for MTUs is quite big (the smallest possible MTU is 1200, and the highest"] # [doc = " is 65527), Quinn performs a binary search to keep the number of probes as low as possible. The"] # [doc = " lower bound of the search is equal to [`TransportConfig::initial_mtu`] in the"] # [doc = " initial MTU discovery run, and is equal to the currently discovered MTU in subsequent runs. The"] # [doc = " upper bound is determined by the minimum of [`MtuDiscoveryConfig::upper_bound`] and the"] # [doc = " `max_udp_payload_size` transport parameter received from the peer during the handshake."] # [doc = ""] # [doc = " # Black hole detection"] # [doc = ""] # [doc = " If, at some point, the network path no longer accepts packets of the detected size, packet loss"] # [doc = " will eventually trigger black hole detection and reset the detected MTU to 1200. In that case,"] # [doc = " MTU discovery will be triggered after [`MtuDiscoveryConfig::black_hole_cooldown`] (ignoring the"] # [doc = " timer that was set based on [`MtuDiscoveryConfig::interval`])."] # [doc = ""] # [doc = " # Interaction between peers"] # [doc = ""] # [doc = " There is no guarantee that the MTU on the path between A and B is the same as the MTU of the"] # [doc = " path between B and A. Therefore, each peer in the connection needs to run MTU discovery"] # [doc = " independently in order to discover the path's MTU."] # [derive (Clone , Debug)] pub struct MtuDiscoveryConfig { pub (crate) interval : Duration , pub (crate) upper_bound : u16 , pub (crate) minimum_change : u16 , pub (crate) black_hole_cooldown : Duration , }
